using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using System.Web.Script.Serialization;
internal sealed class GoogleClientConfig {public string client_id="",client_secret="";}
internal sealed class GoogleSession {public string scope="";public string access_token="",refresh_token="",email="",displayName="";public long expiresTicks;}
internal sealed class GoogleVault {
 internal readonly string Root;static readonly byte[] Entropy=Encoding.UTF8.GetBytes("MonEspace.Google.v1");static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=65536};
 internal GoogleVault(string root){Root=root;}
 internal T Read<T>(string name)where T:class{string path=Path.Combine(Root,name+".bin");if(!File.Exists(path))return null;return Json.Deserialize<T>(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(path),Entropy,DataProtectionScope.CurrentUser)));}
 internal void Write<T>(string name,T value){Directory.CreateDirectory(Root);string path=Path.Combine(Root,name+".bin"),temp=path+".tmp";byte[] bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(Json.Serialize(value)),Entropy,DataProtectionScope.CurrentUser);File.WriteAllBytes(temp,bytes);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
 internal void ClearSession(){string path=Path.Combine(Root,"session.bin");if(File.Exists(path))File.Delete(path);}
 internal static GoogleClientConfig ParseConfig(string json){var root=Json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json);object installed;if(root==null||!root.TryGetValue("installed",out installed))throw new InvalidDataException("Importez le JSON d’un client OAuth Google de type Application de bureau.");var values=installed as System.Collections.Generic.Dictionary<string,object>;if(values==null)throw new InvalidDataException("Configuration Google invalide.");object id,secret;var config=new GoogleClientConfig{client_id=values.TryGetValue("client_id",out id)?Convert.ToString(id):"",client_secret=values.TryGetValue("client_secret",out secret)?Convert.ToString(secret):""};if(config.client_id.Length>512||!System.Text.RegularExpressions.Regex.IsMatch(config.client_id,@"^[A-Za-z0-9_.-]+\.apps\.googleusercontent\.com$")||config.client_secret.Length>512||config.client_secret.Contains("\r")||config.client_secret.Contains("\n"))throw new InvalidDataException("Identifiant OAuth Google invalide.");return config;}
 internal void ImportConfig(string path){if(new FileInfo(path).Length>65536)throw new InvalidDataException("Le fichier de configuration est trop volumineux.");var config=ParseConfig(File.ReadAllText(path));Write("client",config);ClearSession();}
 internal static void Test(string folder){var config=ParseConfig("{\"installed\":{\"client_id\":\"123-test.apps.googleusercontent.com\",\"client_secret\":\"local-test\"}}");var vault=new GoogleVault(Path.Combine(folder,"google-vault"));try{vault.Write("client",config);}catch(CryptographicException){File.WriteAllText(Path.Combine(folder,"GOOGLE_VAULT_CHECK.txt"),"SKIPPED: Windows DPAPI unavailable for the host account profile. No plaintext fallback. Verify on the target Windows desktop.");return;}vault.Write("session",new GoogleSession{refresh_token="test-refresh",email="test@example.com"});if(vault.Read<GoogleClientConfig>("client").client_id!=config.client_id||vault.Read<GoogleSession>("session").refresh_token!="test-refresh")throw new Exception("Chiffrement local Google");if(Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(vault.Root,"session.bin"))).Contains("test-refresh"))throw new Exception("Jeton Google en clair");vault.ClearSession();if(vault.Read<GoogleSession>("session")!=null)throw new Exception("Déconnexion locale");File.WriteAllText(Path.Combine(folder,"GOOGLE_VAULT_CHECK.txt"),"PASS: Windows DPAPI encrypted roundtrip, no plaintext token, local session deletion.");}
}
